parameters.query:
SELECT 
    'Setup Complete!' as status,
    (
        SELECT COUNT(*) FROM information_schema.tables 
        WHERE table_schema = DATABASE() 
        AND table_name IN ('config', 'monitored_urls', 'health_reports', 'alert_groups', 'alert_group_members', 'url_alert_groups', 'alert_history')
    ) as tables_created,
    (
        SELECT COUNT(*) FROM config
    ) as config_entries,
    (
        SELECT COUNT(*) FROM monitored_urls
    ) as sample_urls,
    (
        SELECT COUNT(*) FROM alert_groups
    ) as alert_groups,
    (
        SELECT COUNT(*) FROM alert_group_members
    ) as alert_members,
    (
        SELECT COUNT(*) FROM url_alert_groups
    ) as url_group_links,
    NOW() as setup_completed_at;

